        unsigned long fileBlocks = (m_size + m_blockSize - 1) / m_blockSize;
        unsigned long remaining = fileBlocks - (m_firstBlock + m_blockCount);
        if (claim > remaining) claim = remaining;
        for (; claim != 0; --claim) {
